// diffItem represents a difficulty option.
type diffItem struct {
	label string
	clues string
	desc  string
	diff  generator.Difficulty
}

var diffItems = []diffItem{
	{"EASY", "36-40 clues", "Solvable with naked and hidden singles only. A warm-up.", generator.Easy},
	{"MEDIUM", "30-35 clues", "Requires naked pairs and pointing pairs. Good daily practice.", generator.Medium},
	{"HARD", "25-29 clues", "Advanced patterns required. Focused solving needed.", generator.Hard},
	{"EXPERT", "17-24 clues", "X-Wing, Y-Wing, and Swordfish. Not for the faint-hearted.", generator.Expert},
}

// menuLabel is a simple label+index pair for menu items.
type menuLabel struct {
	label string
}

var menuLabels = []menuLabel{
	{"New Game"},
	{"Puzzle Library"},
	{"History"},
	{"Themes"},
	{"Quit"},
}

// themeItem represents a selectable theme.
type themeItem struct {
	key   string
	label string
}

var themeItems = []themeItem{
	{"modern-charm", "Modern Charm"},
	{"zen-monolith", "Zen Monolith"},
	{"retro-phosphor", "Retro Phosphor"},
	{"matrix", "Matrix"},
}

// Model is the main menu screen.
type Model struct {
	cursor       int
	width        int
	height       int
	showDiff     bool
	diffCursor   int
	showTheme    bool
	themeCursor  int
	activeTheme  string
	theme        *theme.Theme
	generating   bool
	hasSavedGame bool
}

// New creates a new menu model.
func New(th *theme.Theme, hasSavedGame bool) *Model {
	themeCursor := 0
	for i, item := range themeItems {
		if item.key == th.Name {
			themeCursor = i
			break
		}
	}
	return &Model{theme: th, activeTheme: th.Name, themeCursor: themeCursor, hasSavedGame: hasSavedGame}
}

// SetHasSavedGame updates whether a saved game is available to resume.
func (m *Model) SetHasSavedGame(has bool) {
	m.hasSavedGame = has
	if m.cursor > m.maxCursor() {
		m.cursor = m.maxCursor()
	}
}

func (m *Model) effectiveItems() []menuLabel {
	if m.hasSavedGame {
		return append([]menuLabel{{"Resume Game"}}, menuLabels...)
	}
	return menuLabels
}

func (m *Model) maxCursor() int {
	return len(m.effectiveItems()) - 1
}

// SetTheme updates the theme on the menu model.
func (m *Model) SetTheme(th *theme.Theme) {
	m.theme = th
	m.activeTheme = th.Name
	for i, item := range themeItems {
		if item.key == th.Name {
			m.themeCursor = i
			break
		}
	}
}

func (m *Model) Init() tea.Cmd {
	return nil
}

func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyMsg:
		if m.generating {
			return m, nil
		}
		if m.showDiff {
			return m, m.handleDiffKey(msg)
		}
		if m.showTheme {
			return m, m.handleThemeKey(msg)
		}
		return m, m.handleMenuKey(msg)

	case generateMsg:
		return m, m.startGenerate(msg.diff)
	}

	return m, nil
}

func (m *Model) handleMenuKey(msg tea.KeyMsg) tea.Cmd {
	switch msg.String() {
	case "up", "w":
		if m.cursor > 0 {
			m.cursor--
		}
	case "down", "s":
		if m.cursor < m.maxCursor() {
			m.cursor++
		}
	case "enter", " ":
		return m.activateItem(m.cursor)
	case "q", "esc", "ctrl+c":
		return tea.Quit
	}
	return nil
}

func (m *Model) activateItem(idx int) tea.Cmd {
	if m.hasSavedGame {
		if idx == 0 {
			return func() tea.Msg { return msgs.ResumeGameMsg{} }
		}
		idx-- // shift to base indices
	}
	switch idx {
	case 0: // New Game
		m.showDiff = true
		return nil
	case 1: // Puzzle Library
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenLibrary} }
	case 2: // History
		return func() tea.Msg { return msgs.NavigateMsg{To: msgs.ScreenHistory} }
	case 3: // Themes
		m.showTheme = true
		return nil
	case 4: // Quit
		return tea.Quit
	}

